import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
}

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];
const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

beforeEach(() => {
  logLines.length = 0;
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
  setLogger();
});

const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: userId}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') {
        connected = frame;
        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      frames.push(frame);
    });
  });
  return {connected, frames};
};

// A store with only the five required members, so listFor can be omitted, recorded or made to throw.
const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const inner = new InMemorySessionStore();
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return summaries;
      },
    };
    const url = await startEngine(store, 'u1');
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, frames}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const withoutList = await startEngine(delegatingTo(inner));
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

    expect({
      unimplemented: unimplemented.frames,
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const inner = new InMemorySessionStore();
    let calls = 0;
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: () => {
        calls += 1;
        return [];
      },
    };
    const url = await startEngine(store);
    const badFrames = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const codes: Array<string | undefined> = [];
    for (const bad of badFrames) {
      const {frames} = await askAfterConnect(url, bad);
      codes.push(frames[0]?.code);
    }
    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: [{type: 'session_list', sessions: []}],
      calls: 1,
    });
  });
});

import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServer, HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.

const servers: Array<{stop: () => Promise<void>}> = [];
const clients: WebSocket[] = [];

/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
export const answeringOrchestrator: ChatOrchestrator = {
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hi'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
export async function startEngineWith(
  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
): Promise<{url: string; hal: HalServer}> {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    ...options,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  return new Promise<string[]>(resolve => {
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
  });
}

/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
export function askOnOpen(
  url: string,
  {until = 'stream_end', token}: {until?: string; token?: string} = {}
): {client: WebSocket; finished: Promise<string[]>} {
  const client = connectClient(url, token);
  const finished = framesUntil(client, until);
  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
  return {client, finished};
}

/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
export function announcedId(client: WebSocket): () => string {
  let sessionId = '';
  client.on('message', raw => {
    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
  });
  return () => sessionId;
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) await hal.stop();
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}

import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  describe('list_sessions', () => {
    it('accepts a bare list_sessions frame', () => {
      const result = validateMessage({type: 'list_sessions'});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
    });

    it('accepts list_sessions with valid limit and before, dropping unknown fields', () => {
      const result = validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {sessionId: 'foo', updatedAt: '2021-01-01T00:00:00.000Z'},
        userId: 'ignored',
      });
      expect(result).toEqual({
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 10,
          before: {sessionId: 'foo', updatedAt: '2021-01-01T00:00:00.000Z'},
        },
      });
    });

    it('rejects list_sessions with non-integer or negative limit', () => {
      expect(validateMessage({type: 'list_sessions', limit: '10'})).toEqual({
        valid: false,
        error: 'limit must be a non-negative integer',
      });
      expect(validateMessage({type: 'list_sessions', limit: 1.5})).toEqual({
        valid: false,
        error: 'limit must be a non-negative integer',
      });
      expect(validateMessage({type: 'list_sessions', limit: -1})).toEqual({
        valid: false,
        error: 'limit must be a non-negative integer',
      });
    });

    it('rejects list_sessions with malformed before cursor', () => {
      expect(validateMessage({type: 'list_sessions', before: {sessionId: 'foo'}})).toEqual({
        valid: false,
        error: 'before.updatedAt must be a date string or number',
      });
      expect(validateMessage({type: 'list_sessions', before: {updatedAt: '2021-01-01T00:00:00.000Z'}})).toEqual({
        valid: false,
        error: 'before.sessionId must be a string of 1-128 characters',
      });
      expect(
        validateMessage({type: 'list_sessions', before: {sessionId: '', updatedAt: '2021-01-01T00:00:00.000Z'}})
      ).toEqual({
        valid: false,
        error: 'before.sessionId must be a string of 1-128 characters',
      });
      expect(validateMessage({type: 'list_sessions', before: {sessionId: 'a'.repeat(129), updatedAt: 12345}})).toEqual({
        valid: false,
        error: 'before.sessionId must be a string of 1-128 characters',
      });
      expect(validateMessage({type: 'list_sessions', before: {sessionId: 'foo', updatedAt: 'not-a-date'}})).toEqual({
        valid: false,
        error: 'before.updatedAt must be a valid date string or number',
      });
    });
  });
});

